import os
import sqlite3
from datetime import datetime
from contextlib import contextmanager
import config

if config.DB_ENGINE == 'mysql':
    import mysql.connector

def get_image_url(item_id):
    local_path = f"static/images/items/{item_id}.jpg"
    if os.path.exists(local_path):
        return f"/{local_path}"
    return f"https://archford.com/Content/images/items/{item_id}.jpg"

# ─────────────────────────────────────────────
# DATABASE INIT
# ─────────────────────────────────────────────
def get_db():
    conn = sqlite3.connect(config.SQLITE_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    """Create all tables and seed data if users table is missing or empty."""
    conn = get_db()
    c = conn.cursor()

    # Create tables always
    # USERS (mirrors dbo_AR_MasterTable)
    c.execute('''CREATE TABLE IF NOT EXISTS users (
        username TEXT PRIMARY KEY,
        password TEXT NOT NULL,
        school_name TEXT,
        customer_id TEXT,
        contact_name TEXT,
        address TEXT,
        city TEXT,
        state TEXT,
        zip TEXT,
        phone TEXT,
        email TEXT,
        tax_code TEXT,
        discount_code TEXT,
        terms_code TEXT
    )''')

    # INVENTORY CODES (mirrors dbo_IN_InventoryCode)
    c.execute('''CREATE TABLE IF NOT EXISTS inventory_codes (
        code TEXT PRIMARY KEY,
        description TEXT,
        tax_flag INTEGER DEFAULT 0,
        sales_tax_code TEXT
    )''')

    # PRODUCTS (mirrors dbo_IN_Master)
    c.execute('''CREATE TABLE IF NOT EXISTS products (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        description TEXT,
        vendor TEXT,
        cat TEXT NOT NULL,
        pkg TEXT,
        price REAL NOT NULL,
        price2 REAL,
        price3 REAL,
        price4 REAL,
        price5 REAL,
        img TEXT,
        taxable INTEGER DEFAULT 0,
        active INTEGER DEFAULT 1,
        location TEXT DEFAULT 'MAIN'
    )''')

    # ORDERS (mirrors dbo_WebOrderExport)
    c.execute('''CREATE TABLE IF NOT EXISTS orders (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_num TEXT UNIQUE,
        username TEXT,
        school TEXT,
        contact TEXT,
        email TEXT,
        phone TEXT,
        address TEXT,
        city TEXT,
        state TEXT,
        zip TEXT,
        po_number TEXT,
        payment TEXT,
        ship_later TEXT DEFAULT 'N',
        notes TEXT,
        subtotal REAL,
        shipping REAL,
        total REAL,
        status TEXT DEFAULT 'Pending',
        created_at TEXT
    )''')

    # ORDER ITEMS
    c.execute('''CREATE TABLE IF NOT EXISTS order_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_num TEXT,
        item_id TEXT,
        name TEXT,
        description TEXT,
        cat TEXT,
        pkg TEXT,
        qty INTEGER,
        unit_price REAL,
        tax_code TEXT,
        taxable INTEGER DEFAULT 0,
        line_total REAL,
        FOREIGN KEY (order_num) REFERENCES orders(order_num)
    )''')

    # SETTINGS (for contact info etc)
    c.execute('''CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT
    )''')
    
    # Default contact info
    c.execute('INSERT OR IGNORE INTO settings VALUES ("address", "2200 Prince Street\nConway, AR 72032")')
    c.execute('INSERT OR IGNORE INTO settings VALUES ("phone", "(800) 555-ARCH (2724)")')
    c.execute('INSERT OR IGNORE INTO settings VALUES ("hours", "Mon-Fri, 8:00am - 5:00pm CST")')

    # Check if seeding is needed
    c.execute('SELECT COUNT(*) FROM users')
    if c.fetchone()[0] == 0:
        print("Seeding database...")
        _seed_inventory_codes(conn)
        _seed_products(conn)
        _seed_users(conn)

    conn.commit()
    conn.close()

# ─────────────────────────────────────────────
# SEED INVENTORY CODES
# ─────────────────────────────────────────────
def _seed_inventory_codes(conn):
    codes = [
        ('AA', 'ART', 0, 'NT'),
        ('BB', 'ATHLETIC', 0, '15-04'),
        ('CC', 'CUSTODIAL', 0, '15-04'),
        ('DD', 'OFFICE SUPPLIES', 0, '15-04'),
        ('EE', 'EQUIPMENT/FURNITURE', 0, '15-04'),
        ('G2', 'INSTRUCTIONAL SUPPLIES', 0, 'NT'),
        ('GG', 'INSTRUCTIONAL SUPPLIES', 0, '15-04'),
        ('H2', 'PAPER PRODUCTS', 0, '15-04'),
        ('HH', 'PAPER PRODUCTS', 0, '15-04'),
        ('KK', 'COMPUTER', 0, '15-04'),
        ('LL', 'PROJECTION LAMPS', 0, 'NT'),
        ('M2', 'MARKERS/PENS', 0, 'NT'),
        ('MM', 'MARKERS/PENS', 0, '15-04'),
        ('R2', 'READING SUPPLIES', 0, 'NT'),
        ('RR', 'READING SUPPLIES', 0, '15-04'),
        ('VV', 'AUDIO/VISUAL', 0, 'NT'),
        ('XX', 'MISC', 0, '15-04'),
    ]
    conn.executemany(
        'INSERT OR IGNORE INTO inventory_codes VALUES (?,?,?,?)', codes)
    conn.commit()

