def get_categories():
    conn = get_db()
    cats = conn.execute(
        'SELECT DISTINCT cat FROM products WHERE active=1 ORDER BY cat'
    ).fetchall()
    conn.close()
    cat_icons = {
        'ART': '🎨',
        'OFFICE SUPPLIES': '📎',
        'PAPER PRODUCTS': '📄',
        'CUSTODIAL': '🧹',
        'INSTRUCTIONAL SUPPLIES': '📚',
        'MARKERS/PENS': '✏️',
        'COMPUTER': '💻',
        'ATHLETIC': '⚽',
        'AUDIO/VISUAL': '📽️',
        'EQUIPMENT/FURNITURE': '🪑',
        'READING SUPPLIES': '📖',
        'PROJECTION LAMPS': '💡',
    }
    result = [{'id': 'ALL', 'label': 'All Products', 'icon': '🛒', 'count': 0}]
    total = 0
    for row in cats:
        cat = row['cat']
        conn2 = get_db()
        count = conn2.execute(
            'SELECT COUNT(*) as c FROM products WHERE cat=? AND active=1', (cat,)
        ).fetchone()['c']
        conn2.close()
        total += count
        result.append({
            'id': cat,
            'label': cat.title(),
            'icon': cat_icons.get(cat, '📦'),
            'count': count
        })
    result[0]['count'] = total
    return result

def get_products(category='ALL', search='', sort='default'):
    conn = get_db()
    query = 'SELECT * FROM products WHERE active=1'
    params = []
    if category and category != 'ALL':
        query += ' AND cat=?'
        params.append(category)
    if search:
        query += ' AND (name LIKE ? OR id LIKE ? OR description LIKE ? OR cat LIKE ?)'
        s = f'%{search}%'
        params.extend([s, s, s, s])
    if sort == 'price_asc':
        query += ' ORDER BY price ASC'
    elif sort == 'price_desc':
        query += ' ORDER BY price DESC'
    elif sort == 'name_asc':
        query += ' ORDER BY name ASC'
    else:
        query += ' ORDER BY cat, name'
    products = conn.execute(query, params).fetchall()
    conn.close()
    result = []
    for p in products:
        d = dict(p)
        d['img'] = get_image_url(d['id'])
        result.append(d)
    return result

def get_product(item_id):
    conn = get_db()
    product = conn.execute(
        'SELECT * FROM products WHERE id=?', (item_id,)
    ).fetchone()
    conn.close()
    if product:
        d = dict(product)
        d['img'] = get_image_url(d['id'])
        return d
    return None

